G=load()
def cc(C):
    seen=set(); out=[]
    for c in C:
        if c in seen: continue
        q=deque([c]); seen.add(c); cl=[c]
        while q:
            a,b=q.popleft()
            for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                n=(a+da,b+db)
                if n in set(C) and n not in seen:
                    seen.add(n); q.append(n); cl.append(n)
        out.append(cl)
    return out
def solve(inp,debug=False):
    H,W=len(inp),len(inp[0])
    cnt=Counter(v for r in inp for v in r); bg=cnt.most_common(1)[0][0]
    D=dd(list)
    for y in range(H):
        for x in range(W):
            if inp[y][x]!=bg: D[inp[y][x]].append((y,x))
    CS=dd(list)
    for c,v in D.items():
        S=set(v)
        for comp in cc(S): CS[c].append(comp)
    colcount=Counter({c:len(v) for c,v in D.items()})
    marks=[]; objs=[]
    for c,v in D.items():
        if c==bg: continue
        singles=[x[0] for x in CS[c] if len(x)==1]
        big=[x for x in CS[c] if len(x)>1]
        if singles: marks.extend(singles)
        if big: objs.extend(big)
    # classify: object = comp whose color count==1 OR comp size>1; marker = singleton whose color count>=2
    objlist=[]
    for c,v in D.items():
        if c==bg or colcount[c]>=2:
            for comp in CS[c]:
                if len(comp)>1: objlist.append((c,comp))
        else:
            for comp in CS[c]:
                if len(comp)==1: objlist.append((c,comp))
    marks=[(c,p[0]) for c,p in D.items() if colcount[c]>=2]
    res=[[bg]*W for _ in range(H)]
    placed=defaultdict(bool)
    def occupied(p):
        return res[p[0]][p[1]]!=bg
    for mk in sorted(marks,key=lambda m:m[1]):
        mc=D[mk[0]]
        if len(mc)!=1: continue
        mkp=mc[0]
        best=None
        for oc,ocomp in objlist:
            for sy in range(-H,H):
                for sx in range(-W,W):
                    P={(mkp[0]+sy+a,mkp[1]+sx+b) for a,b in ocomp}
                    if any(p[0]<0 or p[0]>=H or p[1]<0 or p[1]>=W for p in P): continue
                    if any(res[p[0]][p[1]]!=bg for p in P): continue
                    dist=max(abs(a-mkp[0])+abs(b-mkp[1]) for a,b in P)
                    key=(dist,oc,sy,sx)
                    if best is None or key<best: best=key
        if best is None: continue
        _,_,sy,sx=best
        for p in {(mkp[0]+sy+a,mkp[1]+sx+b) for a,b in [x for x,y in ocomp]}:
            res[p[0]][p[1]]=None
    # simplify: re-place properly
    res=[[bg]*W for _ in range(H)]
    occ=lambda p: res[p[0]][p[1]]!=bg
    for mk in sorted(marks,key=lambda m:(m[1],m[0])):
        mc=D[mk[0]]
        if len(mc)!=1: continue
        mkp=mc[0]
        cand=[]
        for oc,ocomp in objlist:
            for sy in range(-H,H):
                for sx in range(-W,W):
                    P=[(mkp[0]+sy+a,mkp[1]+sx+b) for a,b in ocomp]
                    if any(p[0]<0 or p[0]>=H or p[1]<0 or p[1]>=W for p in P): continue
                    if any(occ(p) for p in P): continue
                    cand.append(((max(abs(a-mkp[0])+abs(b-mkp[1]) for a,b in P),oc,sy,sx,P)))
        cand.sort()
        for dist,oc,sy,sx,P in cand:
            for p in P: res[p[0]][p[1]]=oc
            break
    return res
